import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { balanceDue, invoiceTotals } from './payments.js';

/**
 * Generate a customer statement showing outstanding invoices and amounts due.
 * @param {string} customerId - The customer ID
 * @param {Array} invoices - All invoices
 * @param {string} asOf - Statement date (YYYY-MM-DD), filters invoices issued on or before this date
 * @returns {{ ok: true, value: { customerId: string, invoices: Array, totalDue: number } } | { ok: false, error: string }}
 */
export function statement(customerId, invoices, asOf) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  // Filter invoices for this customer with appropriate statuses and dates
  const statementInvoices = invoices
    .filter(inv => inv.customerId === customerId)
    .filter(inv => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter(inv => inv.issueDate <= asOf)
    .map(inv => {
      const totals = invoiceTotals(inv);
      const due = balanceDue(inv);
      return {
        number: inv.number,
        issueDate: inv.issueDate,
        dueDate: inv.dueDate,
        total: totals.total,
        due,
      };
    })
    .sort((a, b) => a.issueDate.localeCompare(b.issueDate));

  const totalDue = statementInvoices.reduce((sum, inv) => sum + inv.due, 0);

  return ok({
    customerId,
    invoices: statementInvoices,
    totalDue,
  });
}

